      d.media_landscape,
    ),
    sectionRow(
      m.range_pmesii_section_information_infrastructure,
      "information_infrastructure",
      informationInfrastructureFieldSpecs(),
      d.information_infrastructure,
    ),
    sectionRow(
      m.range_pmesii_section_trust_dynamics,
      "trust_dynamics",
      trustDynamicsFieldSpecs(),
