--- frontends/range-mfe/src/components/pmesii/DimensionBanner.tsx (277 lines) ---
/**
 * DimensionBanner — the per-dimension header band of the PMESII panel
 * (Physical / Informational), carrying the dimension title + the LLM summary.
 *
 * Direction 3 — Vertical Narrative. A <section aria-labelledby> with an <h3>
 * and a 4px border-inline-start accent (logical property, RTL-safe):
 *   physical      → cog-blue   (the established Range data treatment)
 *   informational → cog-violet (AI-adjacent tertiary, present in the shared
 *                   tailwind preset consumed by range-mfe via cogPreset)
 * The summary measure is capped at 68ch for readability (AARPanel idiom).
 *
 * ## Editing (#2148)
 * The two dimension summaries are 2 of the Analysis output's 10 independently
 * editable units — unlike the 8 sub-section cards (SubSectionCard,
 * accordion items), the summaries are NOT collapsible and stay always
 * visible, but get the same per-unit edit affordance: an explicit-Save/
 * Cancel edit mode, modeled on `ComposeTab.tsx`'s `QueuedPostCard` (edit
 * state, enter-edit, Escape-to-cancel, `aria-busy` while saving, and an
 * inline `role="alert"` only on failure — success is always a caller-side
 * toast, never rendered inline here).
 *
 * Editing is opt-in via `onSave`: undefined (the default) renders exactly
 * the read-only markup the dashboard surface has always shown — this
 * component is shared with that read-only dashboard, so nothing about its
 * output may change when the caller never wires a save path.
 *
 * The Edit/Save/Cancel/error-alert markup, the 409-CAS-conflict-exits-edit-
 * mode rule, and the return-focus-to-Edit-on-exit behavior are shared with
 * the other PMESII edit-affordance call sites via `./editControls`; see that
 * module for the rule itself.
 *
 * The Edit control itself is further gated by `isCanonical`, a prop that
 * arrives fully computed from the caller (`useEnvironmentAnalysis.ts`, T14)
 * — this component never inspects the analysis/translation state to derive
 * it. When `isCanonical` is false (a translation is being displayed), the
 * Edit control is replaced by the `range_pmesii_edit_original_hint` hint
 * instead of disappearing outright, so the instructor knows editing is one
 * click (switch to original) away rather than simply unavailable.
 *
 * ## Prop-resync divergence (documented per ContentSourcesCard.tsx:161)
 * range-mfe has two resync-from-props idioms for a component whose local
 * draft state can drift from the prop that seeded it:
 *   - `ContentSourcesCard`'s idiom resyncs unconditionally whenever the
 *     relevant prop values change. That is safe there because its "draft" is
 *     a handful of toggle/enum values with no free-text edit session to
 *     clobber — silently snapping back to the latest prop is exactly the
 *     wanted behavior.
 *   - `DimensionBanner`'s idiom (this file) is the one place the outcome
 *     genuinely differs: while a summary edit is in progress, an incoming
 *     `summary` prop change means the underlying analysis object changed
 *     identity out from under the instructor (a background refetch, someone
 *     else's edit landing, a translation swap). Silently overwriting the
 *     live draft mid-keystroke would be a data-loss bug, so instead this
 *     component EXITS edit mode outright and discards the in-progress draft,
 *     trusting the caller to toast about the change (per the design ruling:
 *     success/changed-elsewhere signalling is always the caller's job, never
 *     inline here). Only when idle does the draft resync straight from
 *     `summary`, which is ContentSourcesCard's plain case.
 */

import {
  type ReactElement,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import {
  classifySaveError,
  EditActions,
  EditAffordance,
  SaveErrorAlert,
  useReturnFocusOnExit,
} from "./editControls";
import type { DimensionSummaryFieldSpec } from "./fieldSpec";

export type DimensionAccent = "physical" | "informational";

const ACCENT_CLASS: Record<DimensionAccent, string> = {
  physical: "border-cog-blue-600 dark:border-cog-blue-300",
  informational: "border-cog-violet-600 dark:border-cog-violet-300",
};

export interface DimensionBannerProps {
  readonly title: string;
  readonly summary: string;
  readonly accent: DimensionAccent;
  /**
   * The fieldSpec.ts entry identifying this dimension's summary field —
   * drives the Edit control's accessible field name
   * (`range_pmesii_field_edit_aria`) instead of hardcoding the summary
   * field's identity. Falls back to `title` when omitted so existing
   * read-only callers (which never pass this) are unaffected.
   */
  readonly field?: DimensionSummaryFieldSpec<DimensionAccent>;
  /**
   * True when the panel is currently displaying canonical (untranslated)
   * content. Computed entirely by the caller (`useEnvironmentAnalysis.ts`)
   * — this component never derives it. The Edit control renders only when
   * this is true; when false it's replaced by the "switch to original to
   * edit" hint. Defaults to true so read-only callers that never pass
   * `onSave` are unaffected either way.
   */
  readonly isCanonical?: boolean;
  /**
   * Opt-in save callback. Undefined (the default) means read-only mode: the
   * dashboard keeps rendering exactly as it does today, with no Edit
   * affordance at all. When provided, an Edit control appears (subject to
   * `isCanonical`) opening a per-unit edit session with explicit
   * Save/Cancel. Success is signalled by the caller via toast — a rejected
   * promise renders an inline `role="alert"` here (a 409 `RangeApiError`
   * renders the CAS-conflict copy; anything else renders the failure
   * message).
   */
  readonly onSave?: (value: string) => Promise<void>;
}

export default function DimensionBanner({
  title,
  summary,
  accent,
  field,
  isCanonical = true,
  onSave,
}: DimensionBannerProps): ReactElement {
  const headingId = useId();
  const textareaId = useId();
  const editable = onSave !== undefined;
  const fieldName = field?.label ?? title;

  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(summary);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const { editBtnRef, markExit } = useReturnFocusOnExit(editing);
  // Mirrors `editing` for the prop-resync effect below without adding
  // `editing` to that effect's own dependency array (see file header — the
  // effect must run off `summary` alone, not re-fire when only `editing`
  // toggles).
  const editingRef = useRef(editing);

  useEffect(() => {
    editingRef.current = editing;
  }, [editing]);

  // Entering edit mode: focus the textarea and drop the caret at the end
  // (ComposeTab's QueuedPostCard idiom).
  useEffect(() => {
    if (!editing) return;
    const el = textareaRef.current;
    if (el) {
      el.focus();
      el.setSelectionRange(el.value.length, el.value.length);
    }
  }, [editing]);

  // Prop resync — see file header for the documented divergence from
  // ContentSourcesCard's idiom. Idle: draft tracks `summary` directly. Mid
  // edit: a `summary` change means the analysis changed elsewhere, so exit
  // edit mode and discard the draft instead of silently overwriting it.
  useEffect(() => {
    if (editingRef.current) {
      setEditing(false);
      setError(null);
      return;
    }
    setDraft(summary);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [summary]);

  const beginEdit = useCallback(() => {
    setError(null);
    setDraft(summary);
    setEditing(true);
  }, [summary]);

  const cancelEdit = useCallback(() => {
    setDraft(summary);
    setError(null);
    // Return focus to Edit on cancel too (Escape + Cancel button both route
    // here), matching the Save path.
    markExit();
    setEditing(false);
  }, [summary, markExit]);

  const canSave = draft.trim().length > 0 && !saving;

  const handleSave = useCallback(async () => {
    if (onSave === undefined || draft.trim().length === 0 || saving) return;
    setSaving(true);
    setError(null);
    try {
      await onSave(draft);
      markExit();
      setEditing(false);
    } catch (err: unknown) {
      // Classification (409-CAS-conflict-exits-edit-mode vs. any other
      // failure keeps the editor open) lives in `classifySaveError`.
      const { message, exit } = classifySaveError(err);
      setError(message);
      if (exit) {
        markExit();
        setEditing(false);
      }
    } finally {
      setSaving(false);
    }
  }, [draft, saving, onSave, markExit]);

  return (
    <section
      aria-labelledby={headingId}
      className={`flex flex-col gap-cog-2 rounded-lg border-s-4 bg-cog-surface-subtle p-cog-4 ${ACCENT_CLASS[accent]}`}
    >
      <div className="flex items-start justify-between gap-cog-3">
        <h3
          id={headingId}
          className="text-heading-sm font-semibold text-cog-text-primary"
        >
          {title}
        </h3>
        {editable && !editing && (
          <EditAffordance
            ref={editBtnRef}
            fieldName={fieldName}
            enabled={isCanonical}
            onEdit={beginEdit}
          />
        )}
      </div>

      {editing ? (
        <div className="flex flex-col gap-cog-2">
          <label htmlFor={textareaId} className="sr-only">
            {m.range_pmesii_field_edit_aria({ field: fieldName })}
          </label>
          <textarea
            id={textareaId}
            ref={textareaRef}
            aria-label={m.range_pmesii_field_edit_aria({ field: fieldName })}
            rows={3}
            value={draft}
            disabled={saving}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                cancelEdit();
              }
            }}
            className="max-w-cog-measure resize-none rounded-lg border border-cog-border/60 bg-cog-surface p-cog-3 text-body-md leading-relaxed text-cog-text-primary focus:outline-none focus-visible:border-cog-blue-600 focus-visible:ring-2 focus-visible:ring-cog-focus disabled:cursor-not-allowed disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary dark:bg-cog-surface"
          />
          <EditActions
            saving={saving}
            canSave={canSave}
            onSave={() => void handleSave()}
            onCancel={cancelEdit}
          />
        </div>
      ) : (
        <p className="max-w-cog-measure text-body-md leading-relaxed text-cog-text-secondary">
          {summary}
        </p>
      )}

      {/* Rendered regardless of edit/read mode: a 409 conflict exits edit
          mode on arrival (see handleSave), so the alert must survive that
          transition rather than living only inside the editing branch. */}
      {error !== null && <SaveErrorAlert message={error} />}
    </section>
  );
}


--- frontends/range-mfe/src/components/pmesii/PMESIIPanel.tsx (365 lines) ---
/**
 * PMESIIPanel — the PMESII environment-analysis region state machine
 * (issue #479), mirroring the AARPanel idiom:
 *
 *   pending   → muted "no analysis yet" card + optional generate CTA
 *               (rendered only when onRegenerate is provided).
 *   computing → role="status" aria-live="polite" spinner + shimmer skeletons.
 *   ready     → Physical DimensionBanner + a single-column stack of 4
 *               collapsible SubSectionCards inside one `Accordion.Root
 *               type="multiple"` (#2149) + Informational banner + its own
 *               4-card stack/Root, with an sr-only aria-live ready
 *               announcement and the generated-at caption. The two Roots are
 *               scoped per dimension so their expand/collapse state stays
 *               independent.
 *   error     → role="alert" danger card; Retry (min 44px hit target) MUST
 *               invoke onRegenerate — error branches need a working retry.
 *
 * Field labels all come from the range_pmesii_* i18n keys; rows whose value is
 * absent are silently omitted by SubSectionCard (protojson optional drops).
 */

import { type ReactElement, useState } from "react";
import { Accordion } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import type { AnalysisStatus, EnvironmentAnalysis } from "../../api/analysis";
import type { UseEnvironmentAnalysisEditingResult } from "../../hooks/useEnvironmentAnalysis";
import { ConfirmDialog } from "../ConfirmDialog";
import DimensionBanner from "./DimensionBanner";
import {
  informationalSections,
  informationalSummaryFieldSpec,
  physicalSections,
  physicalSummaryFieldSpec,
  type PMESIISectionSpec,
} from "./fieldSpec";
import SubSectionCard from "./SubSectionCard";
import TranslationBar, { type TranslationBarState } from "./TranslationBar";

export type PMESIIPanelStatus = AnalysisStatus;

export interface PMESIIPanelProps {
  readonly status: PMESIIPanelStatus;
  readonly analysis: EnvironmentAnalysis | null;
  readonly onRegenerate?: () => void;
  /**
   * Visible label for the READY-state re-run control (#2148/T15). Defaults to
   * `range_pmesii_regenerate_action` ("Re-generate analysis" — the dashboard's
   * own copy). StepAnalysis (the wizard) overrides this to its existing
   * `range_wizard_analysis_rerun` ("Re-run") copy so this control replaces —
   * without changing the visible text of — its former hand-rolled button.
   * Has no effect on the pending/error branches' own labels.
   */
  readonly regenerateLabel?: string;
  readonly errorMessage?: string;
  /**
   * Whether the ready state renders its own "Generated <when>" caption.
   * Defaults to true. Set false when an enclosing surface already shows the
   * timestamp (e.g. EnvironmentAnalysisSection's "Last generated" header) to
   * avoid duplicating it.
   */
  readonly showGeneratedAt?: boolean;
  // ── Optional explicit-translation affordance (issue #479) ───────────────
  // When `translationState` is undefined the TranslationBar is omitted entirely
  // (backward-compat: existing callers/tests are unaffected). The bar mounts in
  // the ready branch only when source and target locale display names differ.
  readonly translationState?: TranslationBarState;
  readonly showOriginal?: boolean;
  readonly onTranslate?: () => void;
  readonly onToggleOriginal?: () => void;
  readonly onDismissTranslationError?: () => void;
  readonly sourceLocaleName?: string;
  readonly targetLocaleName?: string;
  readonly translationErrorMessage?: string;
  /**
   * Opt-in editing wire-up (#2148/T15a) — a SINGLE prop bundling the whole
   * `useEnvironmentAnalysisEditing` result rather than five separate props,
   * so `StepAnalysis.tsx` (under a hard sub-10-line delta budget) only pays
   * one line. `undefined` (the default) means read-only: every card and
   * banner renders byte-for-byte as it did before #2148 — this is what keeps
   * the read-only dashboard (`EnvironmentAnalysisSection.tsx`) unchanged,
   * since editing is wizard-only. When present, its `saveSection` /
   * `savePhysicalSummary` / `saveInformationalSummary` / `isCanonical` /
   * `disabledReason` are forwarded to each `SubSectionCard` and
   * `DimensionBanner` below.
   */
  readonly editing?: UseEnvironmentAnalysisEditingResult;
}

/**
 * One `Accordion.Root type="multiple"` per dimension — scoped so the
 * Physical and Informational dimensions' expand/collapse state stay
 * independent of each other. `defaultValue` lists every section in the
 * dimension so all cards start expanded. A single-column stack (not a grid):
 * a grid of accordions animates badly as items expand/collapse to different
 * heights in the same row.
 */
function SectionStack({
  sections,
  editing,
}: {
  readonly sections: readonly PMESIISectionSpec[];
  /**
   * Undefined → read-only (default items keyed by `title`, no edit props
   * forwarded — byte-for-byte unchanged from before #2148). Present → items
   * key off the real `sectionKey` (required so a save resolves against
   * `fieldSpec.ts`'s `allFieldSpecs`) and each card gets the edit affordance.
   */
  readonly editing?: UseEnvironmentAnalysisEditingResult;
}): ReactElement {
  return (
    <Accordion.Root
      type="multiple"
      defaultValue={sections.map((s) => (editing !== undefined ? s.sectionKey : s.title))}
      className="flex flex-col gap-cog-3"
    >
      {sections.map((s) =>
        editing !== undefined ? (
          <SubSectionCard
            key={s.title}
            title={s.title}
            fields={s.fields}
            sectionKey={s.sectionKey}
            editable
            onSave={editing.saveSection}
            disabledReason={editing.disabledReason}
          />
        ) : (
          <SubSectionCard key={s.title} title={s.title} fields={s.fields} />
        ),
      )}
    </Accordion.Root>
  );
}

const regenerateButtonClassName =
  "inline-flex min-h-tap w-fit items-center rounded-md border border-cog-border px-cog-4 py-cog-2 text-body-sm font-medium text-cog-text-primary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus";

function RegenerateButton({
  label,
  onClick,
}: {
  readonly label: string;
  readonly onClick?: () => void;
}): ReactElement | null {
  if (onClick === undefined) return null;
  return (
    <button type="button" onClick={onClick} className={regenerateButtonClassName}>
      {label}
    </button>
  );
}

function PendingCard({
  onRegenerate,
}: {
  readonly onRegenerate?: () => void;
}): ReactElement {
  return (
    <div className="flex flex-col items-center gap-cog-3 rounded-lg border border-cog-border bg-cog-surface p-cog-8 text-center">
      <p className="text-body-md font-semibold text-cog-text-primary">
        {m.range_pmesii_pending_title()}
      </p>
      <p className="text-body-md text-cog-text-secondary">
        {m.range_pmesii_pending_body()}
      </p>
      <RegenerateButton
        label={m.range_pmesii_generate_action()}
        onClick={onRegenerate}
      />
    </div>
  );
}

export function formatGeneratedAt(iso: string): string {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? iso : d.toLocaleString();
}

export default function PMESIIPanel({
  status,
  analysis,
  onRegenerate,
  regenerateLabel,
  errorMessage,
  showGeneratedAt = true,
  translationState,
  showOriginal = false,
  onTranslate,
  onToggleOriginal,
  onDismissTranslationError,
  sourceLocaleName,
  targetLocaleName,
  translationErrorMessage,
  editing,
}: PMESIIPanelProps): ReactElement {
  // Re-run confirm gate (#2148/T15) — only ever opens from the ready branch's
  // Re-run button below; declared here (not inside that branch) since hooks
  // can't be conditional on status.
  const [confirmRegenerateOpen, setConfirmRegenerateOpen] = useState(false);

  if (status === "computing") {
    return (
      <div
        role="status"
        aria-live="polite"
        className="flex flex-col gap-cog-4 rounded-lg border border-cog-border bg-cog-surface-subtle p-cog-6"
      >
        <div className="flex items-center gap-cog-3">
          <span
            aria-hidden="true"
            className="size-cog-4 animate-spin rounded-pill border-2 border-cog-blue-600 border-t-transparent motion-reduce:animate-none"
          />
          <p className="text-body-md text-cog-text-secondary">
            {m.range_pmesii_computing()}
          </p>
        </div>
        <p className="text-body-sm text-cog-text-tertiary">
          {m.range_pmesii_computing_hint()}
        </p>
        {/* shimmer skeletons standing in for the two dimension blocks */}
        <div className="grid grid-cols-1 gap-cog-3 sm:grid-cols-2">
          {Array.from({ length: 4 }, (_, i) => (
            <div
              key={i}
              aria-hidden="true"
              className="h-cog-11 animate-pulse rounded-lg bg-cog-surface-muted motion-reduce:animate-none"
            />
          ))}
        </div>
      </div>
    );
  }

  if (status === "error") {
    return (
      <div
        role="alert"
        className="flex flex-col gap-cog-3 rounded-lg border border-cog-danger-300 bg-cog-danger-50 p-cog-6 dark:border-cog-danger-dark-border dark:bg-cog-danger-dark-bg"
      >
        <p className="text-body-md font-semibold text-cog-danger-500 dark:text-cog-danger-dark">
          {m.range_pmesii_error()}
        </p>
        <p className="text-body-sm text-cog-text-secondary">
          {errorMessage !== undefined && errorMessage !== ""
            ? errorMessage
            : m.range_pmesii_error_body()}
        </p>
        <RegenerateButton
          label={m.range_pmesii_retry_action()}
          onClick={onRegenerate}
        />
      </div>
    );
  }

  if (status === "pending" || analysis === null) {
    // "ready" with a null analysis is a defensive fallback to the empty state.
    return <PendingCard onRegenerate={onRegenerate} />;
  }

  // ready
  return (
    <div className="flex flex-col gap-cog-5">
      {/* Visually-hidden ready announcement (aria-live polite). */}
      <p aria-live="polite" className="sr-only">
        {m.range_pmesii_ready()}
      </p>
      {showGeneratedAt && analysis.generated_at !== undefined && (
        <p className="text-body-sm text-cog-text-tertiary">
          {m.range_pmesii_generated_at({
            when: formatGeneratedAt(analysis.generated_at),
          })}
        </p>
      )}
      {/* Edit provenance (#2148): surfaced whenever the row has been hand-edited.
          edited_by is deliberately never sent to the client (api/analysis.ts's
          own doc) — only the timestamp is shown, no editor name. */}
      {analysis.edited_at !== undefined && (
        <p className="text-body-sm text-cog-text-tertiary">
          {m.range_pmesii_edited_at({ when: formatGeneratedAt(analysis.edited_at) })}
        </p>
      )}
      {/* Re-run (#2148/T15): a re-run silently overwrites the whole JSONB
          dimension columns (worker design, unchanged by this ticket) — so once
          the row carries an edit, clicking Re-run must confirm the overwrite
          first rather than firing onRegenerate immediately. When edited_at is
          unset the click behaves exactly as it always has (no dialog, no
          extra click). Cancel leaves the analysis completely untouched — it
          never calls onRegenerate. */}
      {onRegenerate !== undefined && (
        <RegenerateButton
          label={regenerateLabel ?? m.range_pmesii_regenerate_action()}
          onClick={() => {
            if (analysis.edited_at !== undefined) {
              setConfirmRegenerateOpen(true);
            } else {
              onRegenerate();
            }
          }}
        />
      )}
      {confirmRegenerateOpen && (
        <ConfirmDialog
          title={m.range_pmesii_regenerate_confirm_title()}
          body={m.range_pmesii_regenerate_confirm_body()}
          confirmLabel={m.range_pmesii_regenerate_confirm_action()}
          cancelLabel={m.range_pmesii_regenerate_confirm_cancel()}
          onConfirm={() => {
            setConfirmRegenerateOpen(false);
            onRegenerate?.();
          }}
          onCancel={() => setConfirmRegenerateOpen(false)}
        />
      )}
      {translationState !== undefined &&
        sourceLocaleName !== undefined &&
        targetLocaleName !== undefined &&
        sourceLocaleName !== targetLocaleName && (
          <TranslationBar
            sourceLocaleName={sourceLocaleName}
            targetLocaleName={targetLocaleName}
            translationState={translationState}
            showOriginal={showOriginal}
            onTranslate={onTranslate ?? (() => undefined)}
            onToggleOriginal={onToggleOriginal ?? (() => undefined)}
            onDismissError={onDismissTranslationError ?? (() => undefined)}
            errorMessage={translationErrorMessage}
          />
        )}
      <DimensionBanner
        title={m.range_pmesii_physical_title()}
        summary={analysis.physical_dimension.summary}
        accent="physical"
        {...(editing !== undefined
          ? {
              isCanonical: editing.isCanonical,
              onSave: editing.savePhysicalSummary,
              field: physicalSummaryFieldSpec(),
            }
          : {})}
      />
      <SectionStack
        sections={physicalSections(analysis.physical_dimension)}
        editing={editing}
      />
      <DimensionBanner
        title={m.range_pmesii_informational_title()}
        summary={analysis.informational_dimension.summary}
        accent="informational"
        {...(editing !== undefined
          ? {
              isCanonical: editing.isCanonical,
              onSave: editing.saveInformationalSummary,
              field: informationalSummaryFieldSpec(),
            }
          : {})}
      />
      <SectionStack
        sections={informationalSections(analysis.informational_dimension)}
        editing={editing}
      />
    </div>
  );
