/**
 * SubSectionCard — one PMESII sub-section (Geography, Demographics, …) as a
 * label/value definition list inside a collapsible cog surface card (#2149).
 *
 * Direction 3 — Vertical Narrative. The card is a collapsible `Accordion.Item`
 * whose trigger carries the section title (an <h4> eyebrow) and whose content
 * is a <dl> of stacked rows (dt = localized field label, dd = the
 * LLM-produced value). Rows whose value is null / undefined / empty are
 * silently omitted — protojson drops unset optionals, and the card must never
 * render a labelled hole. Bare radius tokens (rounded-lg), never rounded-cog-*.
 *
 * Accordion is consumed ONLY via the `@omnicore-platform/ui` barrel —
 * `@radix-ui/*` imports are ESLint-banned in range-mfe. `Accordion.Content`
 * renders with `forceMount` (frontends/ui/src/Accordion.tsx), so collapsed
 * content stays mounted in the DOM; tests must assert collapse via
 * `expectSectionCollapsed` (tests/utils/accordionAssertions.ts), never a
 * presence query.
 *
 * This card does NOT own an `Accordion.Root` — a Root wrapping several cards
 * per dimension does not compose with a per-card Root (two nested/independent
 * Roots per card would fight each other for the id namespace and defeat
 * `type="multiple"` semantics at the dimension level). `PMESIIPanel` supplies
 * one `Accordion.Root type="multiple"` per dimension and this component only
 * renders `Accordion.Item` / `Trigger` / `Content`. The item's `value` is
 * `sectionKey` when the caller supplies it (T12's editing wire-up needs a
 * stable field-spec discriminant to key off of), falling back to `title`
 * otherwise — both are unique per card within one dimension's Root.
 *
 * Because the open/closed state now lives in the parent Root, this component
 * can no longer read it from local state; the expand/collapse aria-label
 * copy instead tracks the trigger's own Radix-managed `data-state` attribute
 * via a small MutationObserver (mirrors the technique `Accordion.Content`
 * itself uses to sync `data-state` onto `hidden`), so the accessible name
 * still reflects the real open/closed state regardless of who owns the Root.
 *
 * `sectionKey`, `editable`, `onSave`, and `disabledReason` (#2148) are wired
 * here to `SubSectionEditForm.tsx` (T12), which owns the edit-state
 * combinatorics in its own file for a fresh per-file coverage budget. The
 * edit affordance is entirely opt-in: `editable` defaults to false, and
 * without both `editable` AND `onSave` this component's DOM output is
 * unchanged from before #2148 — the read-only dashboard this card is shared
 * with keeps rendering exactly as it always has, including the Trigger
 * being the sole direct child of Accordion.Item (no wrapper). Only when
 * editing is enabled does an outer flex row appear, holding the Trigger
 * beside an Edit control — `Accordion.Trigger`'s own wrapper renders
 * `flex-1`, so this composes without touching `frontends/ui/src/Accordion.tsx`.
 *
 * `disabledReason` is how the translated-content edit gate (computed
 * entirely by the caller, `useEnvironmentAnalysis.ts` / T14 — never derived
 * here) reaches this card: its mere presence (any non-undefined string)
 * swaps the Edit button for the `range_pmesii_edit_original_hint` copy,
 * mirroring `DimensionBanner.tsx`'s `isCanonical` gate.
 *
 * Entering/exiting edit mode is owned here (the `editing` boolean) rather
 * than inside `SubSectionEditForm` — that component only exists for the
 * lifetime of one edit session and calls back via `onExit` for Cancel,
 * Escape, a successful save, and a 409 conflict alike; this component
 * decides what "exit" means. The Edit control itself (button vs. hint span)
 * and returning focus to it on exit are shared with `DimensionBanner.tsx`
 * via `editControls.tsx`'s `EditAffordance` / `useReturnFocusOnExit`.
 */

import {
  type ReactElement,
  useCallback,
  useEffect,
  useId,
  useState,
} from "react";
import { Accordion } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { EditAffordance, useReturnFocusOnExit } from "./editControls";
import SubSectionEditForm from "./SubSectionEditForm";

export interface SubSectionField {
  readonly label: string;
  readonly value: string | null | undefined;
}

/**
 * Save handler shape for the editing flow (#2148) — invoked by
 * `SubSectionEditForm` (via this card's `exitEdit`-on-callback wiring) with
 * the section's field-spec discriminant and the edited fields, `""` already
 * mapped back to omission.
 */
export type SubSectionSaveHandler = (
  sectionKey: string,
  fields: readonly SubSectionField[],
) => void | Promise<void>;

interface SubSectionCardCommonProps {
  readonly title: string;
  readonly fields: readonly SubSectionField[];
  /**
   * Human-readable reason editing is unavailable (e.g. viewing a
   * translation). When set (and `editable`+`onSave` are present), the Edit
   * control is replaced by the `range_pmesii_edit_original_hint` text.
   */
  readonly disabledReason?: string;
}

/**
 * Read-only shape (default): editing is either fully absent or only
 * partially opted into (e.g. `editable` alone, with no `onSave` yet — the
 * "read mode unchanged" case `PMESIIPanel`/tests exercise). `sectionKey` is
 * optional here — it doubles as this card's Accordion item `value`, falling
 * back to `title`, but nothing is ever saved through this shape so a bogus
 * key can't reach `resolveFieldKey`.
 */
interface SubSectionCardReadOnlyProps extends SubSectionCardCommonProps {
  readonly sectionKey?: string;
  readonly editable?: boolean;
  readonly onSave?: undefined;
}

/**
 * Editing-enabled shape: whenever a caller supplies `onSave` it MUST also
 * supply the real `sectionKey` field-spec discriminant. Without this, a
 * caller could enable editing with `sectionKey` omitted, and the save would
 * silently fall back to the translated `title` as its section key —
 * `resolveFieldKey` (useEnvironmentAnalysis.ts) then throws on the first
 * Save (BUG B / #2148 follow-up). Modeled as a discriminated union (keyed on
 * `onSave`'s presence, since `undefined` vs. `SubSectionSaveHandler` are
 * disjoint types) rather than a runtime check, so the broken combination is
 * rejected by `pnpm typecheck` instead of surfacing as a production
 * exception.
 */
interface SubSectionCardEditableProps extends SubSectionCardCommonProps {
  readonly sectionKey: string;
  readonly editable: true;
  readonly onSave: SubSectionSaveHandler;
}

export type SubSectionCardProps =
  | SubSectionCardReadOnlyProps
  | SubSectionCardEditableProps;

/**
 * Tracks whether the given trigger element's Radix-managed `data-state` is
 * "open", so the aria-label can reflect the real state even though the
 * open/closed state itself lives in an ancestor `Accordion.Root` this
 * component doesn't own.
 */
function useIsOpenFromDataState(node: HTMLElement | null): boolean {
  const [isOpen, setIsOpen] = useState(
    () => node?.getAttribute("data-state") === "open",
  );

  useEffect(() => {
    if (!node) return;
    const apply = (): void => setIsOpen(node.getAttribute("data-state") === "open");
    apply();
    const observer = new MutationObserver(apply);
    observer.observe(node, { attributes: true, attributeFilter: ["data-state"] });
    return () => observer.disconnect();
  }, [node]);

  return isOpen;
}

export default function SubSectionCard(props: SubSectionCardProps): ReactElement {
  const { title, fields, disabledReason } = props;
  const editable = props.editable ?? false;
  const headingId = useId();
  const [triggerNode, setTriggerNode] = useState<HTMLButtonElement | null>(null);
  const isOpen = useIsOpenFromDataState(triggerNode);
  const setTriggerRef = useCallback((el: HTMLButtonElement | null) => {
    setTriggerNode(el);
  }, []);
  const itemValue = props.sectionKey ?? title;
  // Read-mode empty-value filter — UNCHANGED (byte-for-byte) from before
  // #2148. Edit mode below renders every entry of `fields`, this filtered
  // one only.
  const visible = fields.filter(
    (f): f is { label: string; value: string } =>
      typeof f.value === "string" && f.value !== "",
  );

  const canEdit = editable && props.onSave !== undefined;
  const [editing, setEditing] = useState(false);
  const { editBtnRef, markExit } = useReturnFocusOnExit(editing);

  // BUG A fix: the Edit control (in the header row) is clickable whether
  // the item is open or closed, but the edit form mounts inside
  // Accordion.Content, which force-mounts and hides itself via `hidden`
  // while collapsed (frontends/ui/src/Accordion.tsx). This Root is owned by
  // the caller (PMESIIPanel) and is uncontrolled (`defaultValue` only, no
  // `value`/`onValueChange`) — the only open-state control it exposes to a
  // descendant item is the Trigger's own toggle, so beginEdit opens the item
  // by invoking that same real `<button>` Radix already renders, exactly as
  // a user click would.
  const beginEdit = useCallback(() => {
    if (!isOpen) triggerNode?.click();
    setEditing(true);
  }, [isOpen, triggerNode]);
  const exitEdit = useCallback(() => {
    markExit();
    setEditing(false);
  }, [markExit]);

  const trigger = (
    <Accordion.Trigger
      ref={setTriggerRef}
      aria-label={
        isOpen
          ? m.range_pmesii_section_collapse_aria({ section: title })
          : m.range_pmesii_section_expand_aria({ section: title })
      }
    >
      <h4
        id={headingId}
        className="text-body-md font-semibold text-cog-text-primary"
      >
        {title}
      </h4>
    </Accordion.Trigger>
  );

  return (
    <Accordion.Item
      value={itemValue}
      data-testid="subsection-card"
      className="flex flex-col rounded-lg border border-cog-border bg-cog-surface p-cog-4 shadow-cog-e1"
    >
      {canEdit ? (
        <div className="flex items-center justify-between gap-cog-2">
          {trigger}
          {!editing && (
            <EditAffordance
              ref={editBtnRef}
              fieldName={title}
              enabled={disabledReason === undefined}
              onEdit={beginEdit}
              hintTitle={disabledReason}
            />
          )}
        </div>
      ) : (
        trigger
      )}
      <Accordion.Content role="region" aria-labelledby={headingId}>
        {canEdit && editing && props.onSave !== undefined ? (
          // BUG B fix: `props.onSave !== undefined` narrows `props` to
          // `SubSectionCardEditableProps`, so `props.sectionKey` is a real
          // `string` here — never the `itemValue` (title-fallback) that used
          // to reach `SubSectionEditForm` when a caller omitted
          // `sectionKey`, which made `resolveFieldKey` throw on Save.
          <SubSectionEditForm
            sectionKey={props.sectionKey}
            fields={fields}
            onSave={props.onSave}
            onExit={exitEdit}
          />
        ) : (
          <dl className="flex flex-col gap-cog-2 pt-cog-3">
            {visible.map((f) => (
              <div key={f.label} className="flex flex-col gap-cog-1">
                <dt className="text-body-sm text-cog-text-tertiary">
                  {f.label}
                </dt>
                <dd className="text-body-md text-cog-text-primary">
                  {f.value}
                </dd>
              </div>
            ))}
          </dl>
        )}
      </Accordion.Content>
    </Accordion.Item>
  );
}


