/**
 * SubSectionEditForm — the edit-mode body of a PMESII sub-section card
 * (#2148), mounted by `SubSectionCard.tsx` only while that card is in edit
 * mode. Split into its own file so this edit-state combinatorics gets a
 * fresh 80% per-file coverage budget, separate from `SubSectionCard.tsx`'s
 * already-100%-covered read path.
 *
 * Modeled on `ComposeTab.tsx`'s `QueuedPostCard` idiom, the same idiom
 * `DimensionBanner.tsx` (T13) used for the 2 dimension-summary edits: an
 * explicit Save/Cancel edit session (never optimistic, never
 * autosave-on-blur), Escape cancels, `aria-busy` while saving, and a
 * `role="alert"` rendered only on failure — success is always signalled by
 * the caller via toast, never rendered here. The Save/Cancel markup and the
 * 409-CAS-conflict-exits-edit-mode classification are shared with
 * `DimensionBanner.tsx` and `SubSectionCard.tsx` via `editControls.tsx`
 * (`EditActions`, `SaveErrorAlert`, `classifySaveError`).
 *
 * ## All fields, not just the visible ones
 * `SubSectionCard`'s read mode filters out fields whose value is an empty
 * string (18 of the 38 PMESII fields repo-wide are optional and often come
 * back empty) — that filter is unchanged and lives only in
 * `SubSectionCard.tsx`. This form receives the section's UNFILTERED
 * `fields` (the same array `physicalSections()`/`informationalSections()`
 * in `fieldSpec.ts` build from `allFieldSpecs`) and renders an input for
 * every one of them, empty fields included, with the field's own label as
 * placeholder — so an instructor can add a diagnosis-time bit of context to
 * a field the LLM omitted.
 *
 * Local edit state is a flat `label -> draft string` record (per the
 * `SectionEditState<T>` shape in `api/analysis.ts`), never a mutable mirror
 * of the readonly analysis tree. `SubSectionField` carries only
 * `{label, value}` (no `fieldKey`) — the label is stable and unique within
 * one section's field list, so it doubles as the draft-state key.
 *
 * ## ""→omission on save
 * `SubSectionCard`'s save contract carries edited values back out as
 * `SubSectionField[]`, mirroring the wire shape where protojson omits unset
 * optionals rather than sending `""`. An instructor clearing a field's
 * input (or never filling in an empty one) must round-trip as an omitted
 * field, not a saved empty string — `buildSavedFields` below maps a drafted
 * `""` back to `undefined` for exactly that reason.
 *
 * ## Prop-resync divergence (mirrors DimensionBanner.tsx's documented rule)
 * Because this component only exists for the lifetime of one edit session
 * (`SubSectionCard` mounts it on Edit, unmounts it on exit), there is no
 * "idle" resync case to handle here the way `DimensionBanner` does — idle
 * resync is just `SubSectionCard`'s stateless read path re-rendering off
 * its own `fields` prop, nothing to reconcile. The one case this file DOES
 * own: if `fields` changes *while this form is mounted* (a background
 * refetch or someone else's edit landing mid-session), that is the
 * analysis object changing identity out from under the instructor — the
 * same trigger `DimensionBanner` treats as license to discard the draft
 * rather than silently overwrite it. So on mount this form snapshots a
 * content signature of the fields it started editing from, and if a later
 * `fields` prop diverges from that signature, it calls `onExit()` outright
 * (never merges the incoming values into the live draft).
 *
 * That signature MUST be value-based, not reference-based:
 * `physicalSections()`/`informationalSections()` build a brand-new
 * array-of-objects on every call, so `SubSectionCard`'s `fields` prop gets
 * a new array reference on every parent re-render even when nothing in the
 * underlying analysis changed. A reference-equality check would false-fire
 * on every unrelated re-render and boot the instructor out of an edit in
 * progress for no reason.
 */

import { type ReactElement, useCallback, useEffect, useId, useRef, useState } from "react";
import { classifySaveError, EditActions, SaveErrorAlert } from "./editControls";
import type { SubSectionField, SubSectionSaveHandler } from "./SubSectionCard";

export interface SubSectionEditFormProps {
  readonly sectionKey: string;
  readonly fields: readonly SubSectionField[];
  readonly onSave: SubSectionSaveHandler;
  /**
   * Called to leave edit mode: Cancel, Escape, a successful save, or a 409
   * conflict all route here. `SubSectionCard` owns what "exit" means (flip
   * `editing` back to false, return focus to its Edit control) — this
   * component never touches that state directly.
   */
  readonly onExit: () => void;
}

/** Value-based signature of a fields array, for the mid-edit resync check. */
function fieldsSignature(fields: readonly SubSectionField[]): string {
  return fields.map((f) => `${f.label}\u0000${f.value ?? ""}`).join("\u0001");
}

function buildDraft(fields: readonly SubSectionField[]): Record<string, string> {
  const draft: Record<string, string> = {};
  for (const f of fields) draft[f.label] = f.value ?? "";
  return draft;
}

/**
 * Map the draft back onto SubSectionField[], "" -> omission (undefined).
 * `draft` is always fully populated from these same `fields` by `buildDraft`
 * before this can run, so every `f.label` has a real (possibly empty)
 * string entry — no `?? ""` fallback needed here.
 */
function buildSavedFields(
  fields: readonly SubSectionField[],
  draft: Record<string, string>,
): readonly SubSectionField[] {
  return fields.map((f) => {
    const raw = draft[f.label];
    return { label: f.label, value: raw === "" ? undefined : raw };
  });
}

export default function SubSectionEditForm({
  sectionKey,
  fields,
  onSave,
  onExit,
}: SubSectionEditFormProps): ReactElement {
  const baseId = useId();
  const initialSignatureRef = useRef(fieldsSignature(fields));
  const [draft, setDraft] = useState<Record<string, string>>(() => buildDraft(fields));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Mid-edit resync divergence — see file header. Only fires on a genuine
  // value change from the fields this session started with; a fresh array
  // reference carrying the same label/value pairs is a no-op.
  useEffect(() => {
    if (fieldsSignature(fields) !== initialSignatureRef.current) {
      onExit();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fields]);

  const setFieldDraft = useCallback((label: string, value: string) => {
    setDraft((d) => ({ ...d, [label]: value }));
  }, []);

  const handleEscape = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        onExit();
      }
    },
    [onExit],
  );

  const handleSave = useCallback(async () => {
    if (saving) return;
    setSaving(true);
    setError(null);
    try {
      await onSave(sectionKey, buildSavedFields(fields, draft));
      onExit();
    } catch (err: unknown) {
      // Classification (409 CAS-conflict exits edit mode; anything else
      // keeps the form open with its own message) lives in
      // `classifySaveError` — see editControls.tsx.
      const { message, exit } = classifySaveError(err);
      setError(message);
      if (exit) onExit();
    } finally {
      setSaving(false);
    }
  }, [saving, onSave, sectionKey, fields, draft, onExit]);

  return (
    <div className="flex flex-col gap-cog-3 pt-cog-3">
      {fields.map((f, i) => {
        const fieldId = `${baseId}-${i}`;
        return (
          <div key={f.label} className="flex flex-col gap-cog-1">
            <label htmlFor={fieldId} className="text-body-sm text-cog-text-tertiary">
              {f.label}
            </label>
            <textarea
              id={fieldId}
              rows={2}
              value={draft[f.label]}
              placeholder={f.label}
              disabled={saving}
              onChange={(e) => setFieldDraft(f.label, e.target.value)}
              onKeyDown={handleEscape}
              className="resize-none rounded-lg border border-cog-border/60 bg-cog-surface p-cog-3 text-body-md text-cog-text-primary focus:outline-none focus-visible:border-cog-blue-600 focus-visible:ring-2 focus-visible:ring-cog-focus disabled:cursor-not-allowed disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary"
            />
          </div>
        );
      })}
      <EditActions saving={saving} onSave={() => void handleSave()} onCancel={onExit} />

      {error !== null && <SaveErrorAlert message={error} />}
    </div>
  );
}


