/**
 * TranslationBar — the explicit-translation affordance for the PMESII
 * environment analysis (issue #479, designer Direction 1).
 *
 * Because GetEnvironmentAnalysis now returns the canonical (source-language)
 * content on a cache-miss locale (instead of auto-enqueuing a translation and
 * spinning), the panel never blanks on a locale switch. This bar makes the
 * translation an explicit, AI-flavored action: when the viewer's UI language
 * differs from the analysis source language, it offers a "Translate" CTA,
 * surfaces in-flight progress, then a "Show original / Show translated" toggle.
 *
 * It is purely presentational — a discriminated `translationState` drives the
 * four visuals; the network call, job-progress poll, and locale-flip GET all
 * live in the caller (useEnvironmentAnalysis on the dashboard, StepAnalysis in
 * the wizard). Translation is an AI action, so it wears the AI-violet accent
 * (NOT cog-blue). RTL-safe: justify-between + logical-property utilities, no
 * left/right hardcoding. Honors prefers-reduced-motion on the spinner.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { CloseIcon } from "../icons";

export type TranslationBarState = "idle" | "translating" | "ready" | "error";

export interface TranslationBarProps {
  /** Display name of the analysis source language (e.g. "English"). */
  readonly sourceLocaleName: string;
  /** Display name of the viewer's UI language (e.g. "Deutsch"). */
  readonly targetLocaleName: string;
  readonly translationState: TranslationBarState;
  /** True when the viewer has toggled back to the original (source) content. */
  readonly showOriginal: boolean;
  readonly onTranslate: () => void;
  readonly onToggleOriginal: () => void;
  readonly onDismissError: () => void;
  /** Server failure reason; the generic message is used when absent. */
  readonly errorMessage?: string;
}

const CONTAINER_BASE =
  "flex items-center justify-between gap-cog-3 rounded-md border px-cog-3 py-cog-2";
const CONTAINER_NEUTRAL = `${CONTAINER_BASE} border-cog-border bg-cog-surface-subtle`;
const CONTAINER_DANGER = `${CONTAINER_BASE} border-cog-danger-300 bg-cog-danger-50 dark:border-cog-danger-dark-border dark:bg-cog-danger-dark-bg`;

const LABEL_CLASS = "text-body-sm text-cog-text-tertiary";

const GHOST_BTN =
  "inline-flex min-h-cog-6 items-center gap-cog-2 rounded-md px-cog-3 text-body-sm " +
  "font-medium text-cog-violet-600 hover:bg-cog-surface-muted " +
  "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 " +
  "focus-visible:outline-cog-focus dark:text-cog-violet-300";

export default function TranslationBar({
  sourceLocaleName,
  targetLocaleName,
  translationState,
  showOriginal,
  onTranslate,
  onToggleOriginal,
  onDismissError,
  errorMessage,
}: TranslationBarProps): ReactElement {
  if (translationState === "translating") {
    return (
      <div role="status" aria-live="polite" className={CONTAINER_NEUTRAL}>
        <span className="flex items-center gap-cog-2">
          <span
            aria-hidden="true"
            className="size-cog-3 animate-spin rounded-pill border-2 border-cog-violet-600 border-t-transparent motion-reduce:animate-none dark:border-cog-violet-300"
          />
          <span className={LABEL_CLASS}>{m.range_pmesii_translating()}</span>
        </span>
      </div>
    );
  }

  if (translationState === "error") {
    const message =
      errorMessage !== undefined && errorMessage !== ""
        ? `${m.range_pmesii_translate_error()} — ${errorMessage}`
        : m.range_pmesii_translate_error();
    return (
      <div role="alert" className={CONTAINER_DANGER}>
        <span className="text-body-sm text-cog-danger-500 dark:text-cog-danger-dark">
          {message}
        </span>
        <button
          type="button"
          onClick={onDismissError}
          aria-label={m.range_pmesii_translate_dismiss()}
          className="inline-flex min-h-tap min-w-tap items-center justify-center rounded-md text-cog-danger-500 hover:bg-cog-danger-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus dark:text-cog-danger-dark"
        >
          <CloseIcon size={16} />
        </button>
      </div>
    );
  }

  if (translationState === "ready") {
    return (
      <div className={CONTAINER_NEUTRAL}>
        <span className={LABEL_CLASS}>
          {m.range_pmesii_translated_from({ locale: sourceLocaleName })}
        </span>
        <button
          type="button"
          aria-pressed={showOriginal}
          onClick={onToggleOriginal}
          className={`${GHOST_BTN} ${
            showOriginal ? "text-cog-violet-600 dark:text-cog-violet-300" : ""
          }`}
        >
          {showOriginal
            ? m.range_pmesii_show_translated()
            : m.range_pmesii_show_original()}
        </button>
      </div>
    );
  }

  // idle
  return (
