export interface EditActionsProps {
  readonly saving: boolean;
  /** Defaults to `!saving` (SubSectionEditForm's rule). DimensionBanner passes its own `canSave`. */
  readonly canSave?: boolean;
  readonly onSave: () => void;
  readonly onCancel: () => void;
}

/**
 * The Save/Cancel button pair shown inside an open edit session. Byte-for-
 * byte the markup `DimensionBanner.tsx` and `SubSectionEditForm.tsx` each
 * rendered independently before this extraction.
