      </button>
      <button
        type="button"
        disabled={saving}
        onClick={onCancel}
        className="inline-flex min-h-cog-5-5 items-center rounded-md border border-cog-border/60 bg-cog-surface px-cog-3 text-caption font-medium text-cog-text-primary hover:bg-cog-surface-subtle disabled:cursor-not-allowed disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
      >
