export interface EditAffordanceProps {
  /** Field name interpolated into range_pmesii_field_edit_aria. */
  readonly fieldName: string;
  /** true -> render the Edit button; false -> render the range_pmesii_edit_original_hint span. */
  readonly enabled: boolean;
  readonly onEdit: () => void;
  /** Optional `title` attribute on the hint span (SubSectionCard passes its disabledReason; DimensionBanner passes nothing). */
  readonly hintTitle?: string;
}

/**
 * The Edit control shown when a unit is not currently in edit mode: either
 * the Edit button (when editing this content is currently allowed) or the
 * "switch to original to edit" hint span (when a translation is displayed).
 * Byte-for-byte the markup `DimensionBanner.tsx` and `SubSectionCard.tsx`
 * each rendered independently before this extraction. The ref forwards to
 * the Edit `<button>` so callers can return focus to it on exit
 * (`useReturnFocusOnExit` below).
 */
export const EditAffordance: ForwardRefExoticComponent<
  EditAffordanceProps & RefAttributes<HTMLButtonElement>
> = forwardRef<HTMLButtonElement, EditAffordanceProps>(function EditAffordance(
  { fieldName, enabled, onEdit, hintTitle },
  ref,
) {
  if (!enabled) {
    return (
      <span
        className="shrink-0 text-caption text-cog-text-tertiary"
        title={hintTitle}
      >
        {m.range_pmesii_edit_original_hint()}
      </span>
    );
  }
  return (
    <button
      ref={ref}
      type="button"
      onClick={onEdit}
      aria-label={m.range_pmesii_field_edit_aria({ field: fieldName })}
      className="shrink-0 rounded-md border border-cog-border/60 px-cog-3 py-cog-1 text-caption font-medium text-cog-text-primary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
    >
      {m.range_pmesii_edit_action()}
    </button>
  );
});

/**
 * The inline failure alert shown on a rejected save. Byte-for-byte the
 * markup `DimensionBanner.tsx` and `SubSectionEditForm.tsx` each rendered
 * independently before this extraction. Never rendered on success — success
 * is always signalled by the caller via toast.
 */
export function SaveErrorAlert({ message }: { readonly message: string }): ReactElement {
  return (
    <p role="alert" className="text-caption text-cog-danger-500 dark:text-cog-danger-dark">
      {message}
    </p>
  );
}

export interface ClassifiedSaveError {
  /** Copy to render in the inline alert. */
  readonly message: string;
  /** True when the failure should also exit edit mode (the 409 CAS-conflict case). */
  readonly exit: boolean;
}

/**
 * Classifies a rejected save so its caller can decide whether to stay in
 * edit mode. A 409 `RangeApiError` is the expected race with someone else's
 * edit landing first — show the conflict copy and exit so the unit reflects
 * reality once the caller refetches/toasts. Any other failure keeps the
 * editor open with its own message so the instructor can retry. This is the
 * one place the 409-exits-edit-mode rule lives; `DimensionBanner.tsx` and
 * `SubSectionEditForm.tsx` each duplicated this logic before this
 * extraction.
 */
export function classifySaveError(err: unknown): ClassifiedSaveError {
  if (err instanceof RangeApiError && err.status === 409) {
    return { message: m.range_pmesii_save_conflict(), exit: true };
  }
  const message = err instanceof Error ? err.message : String(err);
  return { message: m.range_pmesii_save_failed({ message }), exit: false };
}

export interface ReturnFocusOnExit {
  // `RefObject<HTMLButtonElement>` (not `| null`) is what React 18's
  // `useRef<HTMLButtonElement>(null)` returns, and it is what a `ref=` prop
  // accepts — widening it to `| null` makes every `ref={editBtnRef}` call site
  // a TS2322.
  readonly editBtnRef: RefObject<HTMLButtonElement>;
  /** Call immediately before flipping `editing` to false, when focus should return to the Edit control. */
  readonly markExit: () => void;
}

/**
 * Returns focus to the Edit control once edit mode exits (Cancel, Escape, a
 * successful save, or a 409 conflict), but only when the caller opted in via
 * `markExit()` before the exit — never leaves it stranded on `<body>` once
 * the edit-mode markup unmounts, and never fires on a resync-triggered exit
 * that didn't go through `markExit()`. Same semantics
 * `DimensionBanner.tsx` and `SubSectionCard.tsx` each implemented
 * independently before this extraction.
 */
export function useReturnFocusOnExit(editing: boolean): ReturnFocusOnExit {
  const editBtnRef = useRef<HTMLButtonElement>(null);
  const focusEditAfterExit = useRef(false);

  useEffect(() => {
    if (!editing && focusEditAfterExit.current) {
      focusEditAfterExit.current = false;
      editBtnRef.current?.focus();
    }
  }, [editing]);

  // Memoized: consumers list `markExit` in their own useCallback dependency
  // arrays (react-hooks/exhaustive-deps requires it), so an unstable identity
  // would churn every callback that exits edit mode on each render.
  const markExit = useCallback((): void => {
    focusEditAfterExit.current = true;
  }, []);

  return { editBtnRef, markExit };
}


