  readonly sectionKey: string;
  readonly fields: readonly SubSectionField[];
}

/** Bind one card's title/sectionKey/field-specs/section payload into a row. */
function sectionRow<Section, SectionKey extends string>(
  title: () => string,
  sectionKey: SectionKey,
  specs: readonly SectionFieldSpec<Section, SectionKey>[],
  section: Section,
): SectionTableRow {
  return { title, sectionKey, fields: buildFields(specs, section) };
}

/**
 * Build the 4 Physical sub-section cards' worth of labelled fields for the
 * given dimension payload. Rows whose value is absent are silently omitted
 * downstream by SubSectionCard (protojson optional drops) — unchanged
 * behavior from the pre-extraction inline builder.
 */
export function physicalSections(d: PhysicalDimension): readonly PMESIISectionSpec[] {
  const table: readonly SectionTableRow[] = [
    sectionRow(m.range_pmesii_section_geography, "geography", geographyFieldSpecs(), d.geography),
    sectionRow(
      m.range_pmesii_section_demographics,
      "demographics",
      demographicsFieldSpecs(),
      d.demographics,
    ),
    sectionRow(
      m.range_pmesii_section_infrastructure,
      "infrastructure",
      infrastructureFieldSpecs(),
      d.infrastructure,
    ),
    sectionRow(m.range_pmesii_section_economic, "economic", economicFieldSpecs(), d.economic),
  ];
  return table.map((r) => ({ title: r.title(), sectionKey: r.sectionKey, fields: r.fields }));
}

/** Build the 4 Informational sub-section cards' worth of labelled fields. */
export function informationalSections(
  d: InformationalDimension,
): readonly PMESIISectionSpec[] {
  const table: readonly SectionTableRow[] = [
    sectionRow(
      m.range_pmesii_section_media_landscape,
      "media_landscape",
      mediaLandscapeFieldSpecs(),
      d.media_landscape,
    ),
    sectionRow(
      m.range_pmesii_section_information_infrastructure,
